function CelCoachScreen({ vehicle, scenario }) {
  const [i, setI] = useState(0);
  const step = applyVariants(scenario.steps[i], vehicle);
  useEffect(() => emitFocus({ part: step.focus_part || 'engine', action: step.id }), [step.id]);

  return (
    <CoachShell
      media={resolveAsset(scenario, step)}
      title={step.title}
      body={step.description}
      safety={step.safety_warning}
      actions={step.action_buttons}
      onAction={(btn) => {
        if (btn.action === 'open_chat') openChat(btn.payload);
        else handleCoachAction(btn, { setI, scenario });
      }}
    />
  );
}
